import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.DGk0zlJw.js";const u=JSON.parse('{"title":"Beacon 任务书（提炼自原始方案，原文见 mission-excerpt.md）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/mission.md","filePath":"zh/mission.md"}'),n={name:"zh/mission.md"};function s(a,o,l,c,g,d){return e(),r("div",null,[...o[0]||(o[0]=[i('<h1 id="beacon-任务书-提炼自原始方案-原文见-mission-excerpt-md" tabindex="-1">Beacon 任务书（提炼自原始方案，原文见 mission-excerpt.md） <a class="header-anchor" href="#beacon-任务书-提炼自原始方案-原文见-mission-excerpt-md" aria-label="Permalink to &quot;Beacon 任务书（提炼自原始方案，原文见 mission-excerpt.md）&quot;">​</a></h1><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p><strong>Beacon = 常驻 Windows 桌面的开发者状态与操作中心（Developer Status &amp; Action Center）</strong>，不是 Web Dashboard。 口号：See what needs your attention. / Your development signal on Windows。 核心：<strong>Signal + Action</strong>——它替你盯着，而不是要你去看（It watches for you）。</p><h2 id="核心产品模型-7-概念" tabindex="-1">核心产品模型（7 概念） <a class="header-anchor" href="#核心产品模型-7-概念" aria-label="Permalink to &quot;核心产品模型（7 概念）&quot;">​</a></h2><ul><li><strong>Widget</strong>：信息与交互的基本单位（GitHub PR Widget、CI Status Widget…）</li><li><strong>Provider</strong>：数据来源（GitHub 首发；Jenkins/GitLab/Agent 等二期）——<strong>Provider First，不写死进 Core</strong>，凭据统一配置避免逐 Widget 重复填 Token</li><li><strong>Action</strong>：可立即执行的操作（Run/Cancel/Retry/Open/Notify），MVP 只做简单 Action（如 workflow_dispatch）</li><li><strong>Workflow</strong>：高级能力，MVP 不做复杂引擎</li><li><strong>Notification</strong>：主动提醒（来自 CI/机器/Workflow/Widget 阈值），走 Windows Notification</li><li>其余概念按原文补全（Machine/Run 等）</li></ul><h2 id="三层交互-progressive-disclosure-不一上来大面板" tabindex="-1">三层交互（Progressive Disclosure，不一上来大面板） <a class="header-anchor" href="#三层交互-progressive-disclosure-不一上来大面板" aria-label="Permalink to &quot;三层交互（Progressive Disclosure，不一上来大面板）&quot;">​</a></h2><ol><li><strong>Status Capsule</strong>：桌面常驻小胶囊，只显示「有没有事」</li><li>快捷层：一键操作按钮 [Build] [Test] [Deploy]</li><li><strong>Detail Window</strong>：需要时展开细节（Build #1024 Status Failed Repo/Branch…）</li></ol><p>入口：<strong>Tray / Hotkey / Dock</strong>。</p><h2 id="重要设计件" tabindex="-1">重要设计件 <a class="header-anchor" href="#重要设计件" aria-label="Permalink to &quot;重要设计件&quot;">​</a></h2><ul><li><strong>Notification Engine</strong>：规则化（IF CI status == Failed → Notify），不是裸 Toast；Severity 统一五级（Info/Success/Warning/Error/Critical），不许 Provider 各自定义状态</li><li><strong>Refresh Strategy 分级</strong>：PR 30~120s、CI 10~30s…不许全量每秒刷；失败显示「Unable to refresh, Last update 2min ago [Retry]」不甩异常</li><li><strong>Offline Mode</strong>：离线可运行</li><li><strong>Local First</strong>：配置本机（%AppData%\\Beacon：config/connections/widgets/pins.json——原方案的 workflows.json 随「MVP 不做 Workflow」未实现），<strong>Secrets 进 Windows Secret Storage，严禁进普通 JSON</strong></li><li><strong>架构原则</strong>：Local First + Provider First；Agent Server 只作 Connector 不写死</li></ul><h2 id="分期" tabindex="-1">分期 <a class="header-anchor" href="#分期" aria-label="Permalink to &quot;分期&quot;">​</a></h2><ul><li><strong>第一阶段（MVP）</strong>：GitHub Provider（PR/CI）、Status Capsule、简单 Action、Notification、Tray/Hotkey、Local 配置；<strong>明确不做</strong>：复杂 Workflow Engine、多 Provider、Agent 联动</li><li><strong>第二阶段</strong>：Jenkins/GitLab/Docker/Machines/Agents/Generic REST Widget、Schedule、Webhook、Workflow、[Run Task] 发往 Agent——走向 Developer Control Plane <ul><li><strong>冻结记录（2026-10-11，master-plan §2.3 拍板②配套）</strong>：GitLab/Docker/Machines/Agents/Workflow/[Run Task]/Control Plane 一律<strong>冻结不做</strong>（长期产品边界，非暂缓）；Generic REST（http.status/http.quota）与 Webhook Action 已落地不受影响；Jenkins 已落地（jenkins.build，开源标准 JSON API，2026-10-11 批3-补31）。</li></ul></li></ul><h2 id="mvp-成功标准-第一版验收" tabindex="-1">MVP 成功标准（第一版验收） <a class="header-anchor" href="#mvp-成功标准-第一版验收" aria-label="Permalink to &quot;MVP 成功标准（第一版验收）&quot;">​</a></h2><p>开发者能做到：开机自启 → 桌面角落一直看到状态 → 一键 Run/Retry 成功，全程<strong>不开浏览器不登 GitHub</strong>。</p><h2 id="实施次序-原方案明确要求" tabindex="-1">实施次序（原方案明确要求） <a class="header-anchor" href="#实施次序-原方案明确要求" aria-label="Permalink to &quot;实施次序（原方案明确要求）&quot;">​</a></h2><p><strong>第一步不是直接写代码</strong>：先产出 ①技术 RFC ②Solution/项目目录 ③MVP Issue 列表，然后 Phase 1 → Phase 2 逐步实现——防止一开始就做成过度复杂的 Dashboard。<strong>文档优先。</strong></p>',16)])])}const p=t(n,[["render",s]]);export{u as __pageData,p as default};
